import{_ as t,o as e,c as o,a2 as c}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Справочник конфигурации","description":"","frontmatter":{"pageId":"admins/configuration","contentRevision":1},"headers":[],"relativePath":"ru/admins/configuration.md","filePath":"ru/admins/configuration.md"}'),r={name:"ru/admins/configuration.md"};function i(n,d,a,l,s,u){return e(),o("div",null,[...d[0]||(d[0]=[c('<h1 id="справочник-конфигурации" tabindex="-1">Справочник конфигурации <a class="header-anchor" href="#справочник-конфигурации" aria-label="Permalink to &quot;Справочник конфигурации&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Настройки привязываются к корневым секциям JSON. Переменная окружения заменяет двоеточия двойными подчёркиваниями и добавляет префикс Rimlink__: например Rimlink__Server__Port=25560, Rimlink__Auth__AdminLogins__0=admin. Для массивов используются индексы, не строка через запятую.</p><p>Настрой окружение службы/контейнера и перезапусти сервер после изменения: руководство не обещает hot reload. Значения ниже — инициализаторы Options, а не пример с заполненными секретами. Пример deploy/appsettings.example.json полезен как шаблон, но не является исчерпывающим контрактом (например, SelfSignedPath отсутствует).</p><p>Полный реестр ключей приведён ниже. undefined Сохраняй единицы при переносе настроек.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Admin:ApiToken, Admin:Tokens:*:Token, Auth:SteamWebApiKey и Server:ServerPassword — секреты. FeedBufferSize 100–100000, FeedPingSeconds 1–300; gift/trade сроки и MaxOpenTrades &gt;=1. Integrity пороги неотрицательны, Freeze не ниже Warn кроме 0. Hygiene: sweep 1–168 ч, неотрицательные возраст/пороги и строго возрастающие 4 уровня. Incidents каталог требует уникальных id, допустимого Kind и положительных множителей; непустой список заменяет весь встроенный каталог.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./security-auth">TLS, вход и права</a></li><li><a href="./gameplay-policy">Игровая политика сервера</a></li></ul><h2 id="reference" tabindex="-1">Все привязываемые ключи <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Все привязываемые ключи {#reference}&quot;">​</a></h2><p>Таблица получена из объявлений Options, а не из примерного JSON. <code>null</code> означает отсутствие значения; строки <code>&quot;&quot;</code> пусты; <code>[]</code> — пустой массив. Выражение <code>Protocol.Limits.*</code> задаёт константу протокола: MaxParcelBytes = 921600, MaxItemsPerParcel = 200, MaxPawnsPerParcel = 10. Ключи с <code>*</code> индексируются начиная с 0.</p><table tabindex="0"><thead><tr><th>Ключ</th><th>Тип</th><th>Значение по умолчанию</th></tr></thead><tbody><tr><td><code>Panel:Enabled</code></td><td><code>bool</code></td><td><code>true</code></td></tr><tr><td><code>Panel:Public</code></td><td><code>bool</code></td><td><code>true</code></td></tr><tr><td><code>Panel:PublicPlayerNames</code></td><td><code>bool</code></td><td><code>true</code></td></tr><tr><td><code>Panel:SessionHours</code></td><td><code>int</code></td><td><code>12</code></td></tr><tr><td><code>Panel:ServerName</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr><tr><td><code>Panel:Description</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr><tr><td><code>Panel:PublicAddress</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr><tr><td><code>Server:Port</code></td><td><code>int</code></td><td><code>25560</code></td></tr><tr><td><code>Server:DataDir</code></td><td><code>string</code></td><td><code>&quot;./data&quot;</code></td></tr><tr><td><code>Server:MaxPlayers</code></td><td><code>int</code></td><td><code>50</code></td></tr><tr><td><code>Server:ServerPassword</code></td><td><code>string?</code></td><td><code>null</code></td></tr><tr><td><code>Server:MaxSettlementsPerPlayer</code></td><td><code>int</code></td><td><code>1</code></td></tr><tr><td><code>Tls:Required</code></td><td><code>bool</code></td><td><code>true</code></td></tr><tr><td><code>Tls:CertificatePath</code></td><td><code>string?</code></td><td><code>null</code></td></tr><tr><td><code>Tls:KeyPath</code></td><td><code>string?</code></td><td><code>null</code></td></tr><tr><td><code>Tls:SelfSignedPath</code></td><td><code>string?</code></td><td><code>null</code></td></tr><tr><td><code>Auth:AllowPassword</code></td><td><code>bool</code></td><td><code>false</code></td></tr><tr><td><code>Auth:SteamWebApiKey</code></td><td><code>string?</code></td><td><code>null</code></td></tr><tr><td><code>Auth:AdminSteamIds</code></td><td><code>long[]</code></td><td><code>[]</code></td></tr><tr><td><code>Auth:AdminLogins</code></td><td><code>string[]</code></td><td><code>[]</code></td></tr><tr><td><code>Economy:Enabled</code></td><td><code>bool</code></td><td><code>true</code></td></tr><tr><td><code>Economy:MaxParcelBytes</code></td><td><code>int</code></td><td><code>Protocol.Limits.EconomyMaxParcelBytes</code></td></tr><tr><td><code>Economy:MaxItemsPerParcel</code></td><td><code>int</code></td><td><code>Protocol.Limits.EconomyMaxItemsPerParcel</code></td></tr><tr><td><code>Economy:MaxPawnsPerParcel</code></td><td><code>int</code></td><td><code>Protocol.Limits.EconomyMaxPawnsPerParcel</code></td></tr><tr><td><code>Economy:MaxLotsPerPlayer</code></td><td><code>int</code></td><td><code>20</code></td></tr><tr><td><code>Economy:MaxPendingParcels</code></td><td><code>int</code></td><td><code>50</code></td></tr><tr><td><code>Economy:LotLifetimeDays</code></td><td><code>int</code></td><td><code>30</code></td></tr><tr><td><code>Economy:MarketFeePercent</code></td><td><code>int</code></td><td><code>0</code></td></tr><tr><td><code>Economy:SendCooldownSeconds</code></td><td><code>int</code></td><td><code>5</code></td></tr><tr><td><code>Economy:GiftDecisionDays</code></td><td><code>int</code></td><td><code>7</code></td></tr><tr><td><code>Economy:TradeLifetimeDays</code></td><td><code>int</code></td><td><code>7</code></td></tr><tr><td><code>Economy:MaxOpenTrades</code></td><td><code>int</code></td><td><code>5</code></td></tr><tr><td><code>Economy:ServerWealthPercent</code></td><td><code>int</code></td><td><code>100</code></td></tr><tr><td><code>Economy:BlockOutflowUnderThreat</code></td><td><code>bool</code></td><td><code>true</code></td></tr><tr><td><code>Economy:StorageFeePercentPerDay</code></td><td><code>double</code></td><td><code>0.5</code></td></tr><tr><td><code>Economy:StorageFreeDays</code></td><td><code>double</code></td><td><code>3</code></td></tr><tr><td><code>Social:MaxBlocks</code></td><td><code>int</code></td><td><code>200</code></td></tr><tr><td><code>Raids:Enabled</code></td><td><code>bool</code></td><td><code>true</code></td></tr><tr><td><code>Raids:MaxRaiders</code></td><td><code>int</code></td><td><code>10</code></td></tr><tr><td><code>Raids:MaxActiveRaidsPerAttacker</code></td><td><code>int</code></td><td><code>1</code></td></tr><tr><td><code>Raids:TargetCooldownHours</code></td><td><code>int</code></td><td><code>8</code></td></tr><tr><td><code>Raids:PairCooldownHours</code></td><td><code>int</code></td><td><code>24</code></td></tr><tr><td><code>Raids:NewbieProtectionDays</code></td><td><code>int</code></td><td><code>3</code></td></tr><tr><td><code>Raids:MinColonyWealth</code></td><td><code>long</code></td><td><code>20000</code></td></tr><tr><td><code>Raids:LootCapPercent</code></td><td><code>int</code></td><td><code>10</code></td></tr><tr><td><code>Raids:LootCapSilver</code></td><td><code>long</code></td><td><code>5000</code></td></tr><tr><td><code>Raids:AllowKidnap</code></td><td><code>bool</code></td><td><code>false</code></td></tr><tr><td><code>Raids:WarnTicks</code></td><td><code>int</code></td><td><code>60000</code></td></tr><tr><td><code>Raids:TimeoutDays</code></td><td><code>int</code></td><td><code>3</code></td></tr><tr><td><code>Raids:ExpireRealDays</code></td><td><code>int</code></td><td><code>7</code></td></tr><tr><td><code>Raids:PeacefulOffDelayHours</code></td><td><code>int</code></td><td><code>24</code></td></tr><tr><td><code>Raids:VisitHours</code></td><td><code>int</code></td><td><code>12</code></td></tr><tr><td><code>Live:Enabled</code></td><td><code>bool</code></td><td><code>true</code></td></tr><tr><td><code>Live:InviteSeconds</code></td><td><code>int</code></td><td><code>60</code></td></tr><tr><td><code>Live:ReconnectWaitMinutes</code></td><td><code>int</code></td><td><code>5</code></td></tr><tr><td><code>Live:GuestPauses</code></td><td><code>int</code></td><td><code>10</code></td></tr><tr><td><code>Live:GuestPauseSeconds</code></td><td><code>int</code></td><td><code>60</code></td></tr><tr><td><code>Live:MaxFrameBytes</code></td><td><code>int</code></td><td><code>262144</code></td></tr><tr><td><code>Live:DeltasPerSecond</code></td><td><code>int</code></td><td><code>20</code></td></tr><tr><td><code>Live:OrdersPerSecond</code></td><td><code>int</code></td><td><code>30</code></td></tr><tr><td><code>Live:HeartbeatTimeoutSeconds</code></td><td><code>int</code></td><td><code>10</code></td></tr><tr><td><code>Live:SweepSeconds</code></td><td><code>int</code></td><td><code>5</code></td></tr><tr><td><code>Admin:ApiToken</code></td><td><code>string?</code></td><td><code>null</code></td></tr><tr><td><code>Admin:Tokens</code></td><td><code>List&lt;ApiTokenOptions&gt;</code></td><td><code>[]</code></td></tr><tr><td><code>Admin:FeedBufferSize</code></td><td><code>int</code></td><td><code>1000</code></td></tr><tr><td><code>Admin:FeedPingSeconds</code></td><td><code>int</code></td><td><code>15</code></td></tr><tr><td><code>Admin:Tokens:*:Name</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr><tr><td><code>Admin:Tokens:*:Token</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr><tr><td><code>Admin:Tokens:*:Scopes</code></td><td><code>string[]</code></td><td><code>[]</code></td></tr><tr><td><code>Integrity:DevMode</code></td><td><code>DevModePolicy</code></td><td><code>DevModePolicy.AdminsOnly</code></td></tr><tr><td><code>Integrity:WealthWarnPerDay</code></td><td><code>long</code></td><td><code>20000</code></td></tr><tr><td><code>Integrity:WealthFreezePerDay</code></td><td><code>long</code></td><td><code>100000</code></td></tr><tr><td><code>Integrity:StorytellerPolicy</code></td><td><code>StorytellerPolicy</code></td><td><code>StorytellerPolicy.Locked</code></td></tr><tr><td><code>Hygiene:ArchiveAfterDays</code></td><td><code>int</code></td><td><code>14</code></td></tr><tr><td><code>Hygiene:ArchiveMaxWealth</code></td><td><code>long</code></td><td><code>100000</code></td></tr><tr><td><code>Hygiene:ArchiveMaxColonyDays</code></td><td><code>int</code></td><td><code>60</code></td></tr><tr><td><code>Hygiene:SweepHours</code></td><td><code>int</code></td><td><code>6</code></td></tr><tr><td><code>Hygiene:WealthTiers</code></td><td><code>long[]?</code></td><td><code>null</code></td></tr><tr><td><code>Incidents:Enabled</code></td><td><code>bool</code></td><td><code>true</code></td></tr><tr><td><code>Incidents:MaxQueuedPerTarget</code></td><td><code>int</code></td><td><code>2</code></td></tr><tr><td><code>Incidents:BasePrice</code></td><td><code>double</code></td><td><code>100</code></td></tr><tr><td><code>Incidents:MinPrice</code></td><td><code>long</code></td><td><code>50</code></td></tr><tr><td><code>Incidents:WarnTicks</code></td><td><code>long</code></td><td><code>30000</code></td></tr><tr><td><code>Incidents:WarnFromLevel</code></td><td><code>int</code></td><td><code>3</code></td></tr><tr><td><code>Incidents:KindCooldownHours</code></td><td><code>double</code></td><td><code>1</code></td></tr><tr><td><code>Incidents:ExpireRealDays</code></td><td><code>double</code></td><td><code>7</code></td></tr><tr><td><code>Incidents:Catalog</code></td><td><code>List&lt;IncidentCatalogEntry&gt;</code></td><td><code>[]</code></td></tr><tr><td><code>Incidents:Catalog:*:Id</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr><tr><td><code>Incidents:Catalog:*:IncidentDef</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr><tr><td><code>Incidents:Catalog:*:FactionDef</code></td><td><code>string?</code></td><td><code>null</code></td></tr><tr><td><code>Incidents:Catalog:*:Kind</code></td><td><code>string</code></td><td><code>&quot;Hostile&quot;</code></td></tr><tr><td><code>Incidents:Catalog:*:PriceMultiplier</code></td><td><code>double</code></td><td><code>1</code></td></tr><tr><td><code>Incidents:Catalog:*:PodsMultiplier</code></td><td><code>double?</code></td><td><code>null</code></td></tr><tr><td><code>Saves:CompactOldVersions</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p><code>Tls:SelfSignedPath=null</code> выбирает <code>&lt;DataDir&gt;/tls/server.pfx</code>. <code>Hygiene:WealthTiers=null</code> выбирает <code>[50000,150000,400000,1000000]</code>. Panel:ServerName пустой показывает Rimlink, SessionHours ограничивается 1–168, Description обрезается до 1000 символов. <code>Saves:CompactOldVersions=false</code> прекращает создание новых дельт, но не удаляет старые. <code>Server:ProtocolVersion</code> вычисляется, это не конфигурация.</p><h3 id="backup" tabindex="-1">Backup <a class="header-anchor" href="#backup" aria-label="Permalink to &quot;Backup&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ключ</th><th>Тип</th><th>По умолчанию</th></tr></thead><tbody><tr><td><code>Backup:IntervalHours</code></td><td><code>int</code></td><td><code>24</code></td></tr><tr><td><code>Backup:Keep</code></td><td><code>int</code></td><td><code>7</code></td></tr></tbody></table><p>IntervalHours &lt;= 0 отключает расписание, Keep сохраняет хотя бы одну новейшую копию. Ручной backup не заменяет проверку восстановления.</p><h3 id="что-регулируют-секции" tabindex="-1">Что регулируют секции <a class="header-anchor" href="#что-регулируют-секции" aria-label="Permalink to &quot;Что регулируют секции&quot;">​</a></h3><p>Server задаёт порт, каталог, вместимость и пароль общего доступа, не пароль аккаунта. Tls выбирает пару PEM certificate/key или сохранённый самоподписанный сертификат. Auth разрешает парольный вход и назначает администраторов по Steam ID/login; SteamWebApiKey проверяет билеты Steam.</p><p>Economy включает обмен и ограничивает посылки (суммарные bytes/items/pawns), лоты/ожидающие доставки, сроки хранения, комиссию рынка и частоту отправки. GiftDecisionDays и TradeLifetimeDays возвращают escrow после истечения решения/сделки. ServerWealthPercent учитывает серверные активы в богатстве, BlockOutflowUnderThreat блокирует вывод под угрозой; StorageFeePercentPerDay после StorageFreeDays — плата за пешек и скоропортящееся. Social:MaxBlocks ограничивает личный список блокировки.</p><p>Raids регулирует доступность, число атакующих/активных рейдов, кулдауны цели/пары, защиту новичка и минимальное богатство. LootCapPercent и LootCapSilver ограничивают добычу; AllowKidnap — похищение; WarnTicks — игровое предупреждение, undefined, ExpireRealDays — реальный срок, PeacefulOffDelayHours — задержка выхода из мирного режима, VisitHours — срок визита.</p><p>Live задаёт срок приглашения/ожидания восстановления, бюджет пауз гостя, bytes кадра, частоты delta/order и контроль молчания канала. Admin задаёт legacy token панели и именованные token/scopes, размер повтора SSE и интервал ping. Integrity ограничивает dev mode, скачки богатства и storyteller; 0 отключает соответствующий порог. Hygiene архивирует только подходящие по отсутствию, возрасту и богатству колонии, 0 снимает соответствующий фильтр (ArchiveAfterDays=0 выключает sweep).</p><p>Incidents включает платные события, очередь на цель, BasePrice/MinPrice, предупреждение от WarnFromLevel, кулдаун по Kind и срок исполнения. Catalog:* задаёт Id, IncidentDef, необязательный FactionDef, Kind (Hostile/Weather/Kind), PriceMultiplier и необязательный PodsMultiplier. Не обещай поддержку def из отсутствующего мода.</p>',23)])])}const y=t(r,[["render",i]]);export{m as __pageData,y as default};
